original_axiom:
sosa:hosts owl:inverseOf sosa:isHostedBy .
sosa:hosts rdfs:domain sosa:Platform .
sosa:hosts rdfs:range [ a owl:Class ; owl:unionOf ( sosa:System sosa:Platform ) ] .
sosa:hosts rdfs:subPropertyOf [ a owl:ObjectProperty ;
  owl:propertyChainAxiom ( bfo:bearer_of bfo:has_realization bfo:has_participant )
] .
sosa:isHostedBy rdfs:subPropertyOf [ a owl:ObjectProperty ;
  owl:propertyChainAxiom ( [ owl:inverseOf bfo:has_participant ] bfo:realizes [ owl:inverseOf bfo:bearer_of ] )
] .

sosa:implementedBy rdfs:subPropertyOf [ a owl:ObjectProperty ;
  owl:propertyChainAxiom ( [ owl:inverseOf cco:prescribed_by ] [ owl:inverseOf cco:has_agent ] )
] .

sosa:implements owl:inverseOf sosa:implementedBy .
sosa:implements rdfs:subPropertyOf [ a owl:ObjectProperty ;
  owl:propertyChainAxiom ( cco:agent_in [ owl:inverseOf cco:prescribed_by ] )
] .

sosa:Battery rdfs:subClassOf sosa:System .
sosa:Battery rdfs:subClassOf [ a owl:Restriction ;
  owl:onProperty bfo:bearer_of ;
  owl:someValuesFrom bfo:Function ] .

sosa:hasOperatingConditions rdfs:domain sosa:System .
sosa:hasOperatingConditions rdfs:range [ a owl:Class ;
  owl:unionOf ( sosa:Observation sosa:ObservationCollection ) ] .
sosa:hasOperatingConditions rdfs:subPropertyOf [ a owl:ObjectProperty ;
  owl:propertyChainAxiom ( bfo:bearer_of [ owl:inverseOf cco:is_about ] ) ] .

sosa:hasSystemCapability rdfs:domain sosa:System .
sosa:hasSystemCapability rdfs:range [ a owl:Class ;
  owl:unionOf ( sosa:Observation sosa:ObservationCollection ) ] .
sosa:hasSystemCapability rdfs:subPropertyOf [ a owl:ObjectProperty ;
  owl:propertyChainAxiom ( bfo:bearer_of [ owl:inverseOf cco:is_about ] ) ] .

sosa:hasValidityContext rdfs:domain [ a owl:Class ;
  owl:unionOf ( sosa:Observation sosa:ObservationCollection sosa:Property ) ] .
sosa:hasValidityContext rdfs:range [ a owl:Class ;
  owl:unionOf ( sosa:Observation sosa:ObservationCollection ) ] .
sosa:validityContextOf owl:inverseOf sosa:hasValidityContext .

sosa:OperatingConditions rdfs:subClassOf [ a owl:Class ;
  owl:unionOf ( sosa:Observation sosa:ObservationCollection ) ] .
sosa:OperatingConditions rdfs:subClassOf [ a owl:Restriction ;
  owl:onProperty sosa:hasFeatureOfInterest ;
  owl:someValuesFrom sosa:System ] .

