original_axiom:
sosa-rel:SampleRelationship rdfs:subClassOf cco:InformationContentEntity .
sosa-rel:SampleRelationship rdfs:subClassOf [ a owl:Restriction ;
  owl:onProperty sosa-rel:relatedSample ;
  owl:someValuesFrom sosa:Sample ] .
sosa-rel:SampleRelationship rdfs:subClassOf [ a owl:Restriction ;
  owl:onProperty sosa-rel:natureOfRelationship ;
  owl:someValuesFrom sosa-rel:RelationshipNature ] .

